\plain\par {\listtext\pard\plain\f1\fs24\lang1033 9.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[9].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1491 \'e3\u1512 \'f8\u1513 \'f9\u1492 \'e4 \u1500 \'ec\u1512 \'f8' \u1492 \'e4\u1488 \'e0\u1497 \'e9 \u1490 \'e2\u1488 \'e0\u1493 \'e5\u1503 \'ef}}\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hai Gaon\rquote s}}\plain \f1\lang1033\fs24  sermon on the resurrection of the dead and eschatology (\u8222 \'84rebusque novissimis\ldblquote )) (fol. 263r-v)
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 10.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[10].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1491 \'e3\u1497 \'e9\u1503 \'ef \u1495 \'e7\u1489 \'e1\u1493 \'e5\u1496 \'e8 \u1492 \'e4\u1511 \'f7\u1489 \'e1\u1512 \'f8}}\plain \f1\lang1033\fs24  , chapter from the little book \u8222 \'84Shaalot R. Eliezer\ldblquote 
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 11.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[11].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1505 \'f1\u1508 \'f4\u1512 \'f8 \u1490 \'e2\u1503 \'ef \u1506 \'f2\u1491 \'e3\u1503 \'ef}}\plain \f1\lang1033\fs24  (fol. 264r)
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 12.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[12].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1514 \'fa\u1493 \'e5\u1512 \'f8\u1514 \'fa \u1492 \'e4\u1488 \'e0\u1491 \'e3\u1501 \'ed \u1500 \'ec\u1512 \'f8\u1489 \'e1 \u1504 \'f0\u1495 \'e7\u1502 \'ee\u1503 \'ef}}\plain \f1\lang1033\fs24  (fol. 264v f.), from the larger work of {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Moses Nachman}}\plain \f1\lang1033\fs24 ; compendium on ethics and compendium on what is conducive to cleverness and beauty (\u8222 \'84compendium disciplinae moralis, et de eo, quod prudentiae ac decentiae conveniens est, ex opere majori Mosis Nachmani\ldblquote )
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 13.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[13].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1491 \'e3\u1489 \'e1\u1512 \'f8\u1497 \'e9\u1501 \'ed \u1492 \'e4\u1502 \'ee\u1497 \'e9\u1513 \'f9\u1512 \'f8\u1497 \'e9\u1501 \'ed \u1488 \'e0\u1514 \'fa \u1492 \'e4\u1488 \'e0\u1491 \'e3\u1501 \'ed}}\plain \f1\lang1033\fs24  by the author \u8222 \'84{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1492 \'e4\u1512 \'f8\u1489 \'e1 \u1502 \'ee\u1488 \'e0\u1489 \'e1"\u1512 \'f8\u1488 \'e0}}\plain \f1\lang1033\fs24 \ldblquote  ; a series of aphorisms (\u8222 \'84sententiarum series\ldblquote ) (fol. 268r)
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 14.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[14].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1494 \'e6' \u1502 \'ee\u1496 \'e8\u1497 \'e9\u1489 \'e1\u1497 \'e9 \u1496 \'e8\u1506 \'f2\u1501 \'ed \u1506 \'f2\u1500 \'ec \u1497 \'e9\u1505 \'f1\u1493 \'e5\u1512 \'f8\u1497 \'e9 \u1510 \'f6\u1491 \'e3\u1497 \'e9\u1511 \'f7 \u1493 \'e5\u1496 \'e8\u1493 \'e5\u1489 \'e1 \u1492 \'e4\u1512 \'f8\u1513 \'f9\u1506 \'f2}}
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 15.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[15].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1508 \'f4\u1497 \'e9\u1512 \'f8\u1511 \'f7\u1497 \'e9 \u1512 \'f8' \u1497 \'e9\u1510 \'f6\u1495 \'e7\u1511 \'f7 \u1489 \'e1"\u1512 \'f8 \u1508 \'f4\u1512 \'f8\u1504 \'f0\u1498 \'ea}}
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 16.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[16].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1513 \'f9\u1488 \'e0\u1500 \'ec\u1493 \'e5\u1514 \'fa \u1512 \'f8' \u1488 \'e0\u1500 \'ec\u1497 \'e9\u1506 \'f2\u1494 \'e6\u1512 \'f8}}
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 17.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[17].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1502 \'ee\u1500 \'ec\u1495 \'e7\u1502 \'ee\u1514 \'fa \u1490 \'e2\u1493 \'e5\u1490 \'e2 \u1502 \'ee\u1490 \'e2\u1493 \'e5\u1490 \'e2 \u1493 \'e5\u1502 \'ee\u1513 \'f9\u1497 \'e9\u1495 \'e7 \u1489 \'e1\u1503 \'ef \u1497 \'e9\u1493 \'e5\u1505 \'f1\u1507 \'f3 \u1493 \'e5\u1502 \'ee\u1513 \'f9\u1497 \'e9\u1495 \'e7 \u1489 \'e1\u1503 \'ef \u1491 \'e3\u1493 \'e5\u1491 \'e3}}\plain \f1\lang1033\fs24  (fol. 269 ff.)
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 18.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[18].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1505 \'f1\u1508 \'f4\u1512 \'f8 \u1494 \'e6\u1512 \'f8\u1489 \'e1\u1489 \'e1\u1500 \'ec}}\plain \f1\lang1033\fs24  (fol. 270 b. s.)
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 19.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[19].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1505 \'f1\u1491 \'e3\u1512 \'f8 \u1489 \'e1\u1503 \'ef \u1506 \'f2\u1491 \'e3\u1503 \'ef}}
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 20.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[20].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1497 \'e9\u1510 \'f6\u1497 \'e9\u1512 \'f8\u1514 \'fa \u1492 \'e4\u1493 \'e5\u1500 \'ec\u1491 \'e3}}\plain \f1\lang1033\fs24  ; writing that became infamous due to its tackiness (\u8222 \'84scriptiones insulsitate sua notissimae.\ldblquote )
\plain\par {\listtext\pard\plain\f1\fs24\lang1033 21.\tab}\ls1\ilvl2 {\field{\*\fldinst HYPERLINK "hida://bezwrk[21].6930gi/?u"}{\fldrslt \plain \f2\lang1037\fs24\chcbpat17 \u1513 \'f9\u1488 \'e0\u1500 \'ec\u1514 \'fa \u1492 \'e4\u1514 \'fa\u1500 \'ec\u1502 \'ee\u1497 \'e9\u1491 \'e3\u1497 \'e9\u1501 \'ed \u1500 \'ec\u1512 \'f8\u1489 \'e1\u1501 \'ed}}\plain \f1\lang1033\fs24 , Talmudic haggadae (\u8222 \'84agadae\ldblquote ), followed by a couple of peraqim and midrashim (\u8222 \'84midrasici\ldblquote ) 
\plain\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Wagenseil added some folia which he had cut out of an old and tattered Pentateuch, thereby rescuing the folia. }

