\plain\par \pard\li1080\fi-360\jclisttab\tx0\qj\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f3\fs24\lang1024 \u-4051 ?\tab}\ls8\ilvl1 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 \u1505 ?\u1493 ?\u1491 ?\u1493 ?\u1514 ? \u1502 ?\u1493 ?\u1512 ?\u1492 ?}}
