\pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f2\fs24\lang1033 -\tab}\ls4\ilvl0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1037\fs24\chcbpat17 \u1508 \'f4\u1497 \'e9\u1512 \'f8\u1493 \'e5\u1513 \'f9 \u1506 \'f2\u1500 \'ec \u1505 \'f1\u1508 \'f4\u1512 \'f8 \u1488 \'e0\u1497 \'e9\u1493 \'e5\u1489 \'e1}}\plain \f2\lang1033\fs24  (fol. 329v-373r), commentary on the book Job; \plain \f2\i\lang1033\fs24 no title in the beginning;
\plain\par \pard\fi0\li720\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 added is a colophon by the scribe (\plain \f1\lang1037\fs24 \u1488 \'e0\u1500 \'ec\u1497 \'e9\u1506 \'f2\u1494 \'e6\u1512 \'f8 \u1489 \'e1''\u1512 \'f8 \u1497 \'e9\u1495 \'e7\u1497 \'e9\u1488 \'e0\u1500 \'ec \u1495 \'e7\u1500 \'ec\u1508 \'f4\u1503 \'ef\plain \f2\lang1033\fs24 ) on fol. 373r, who wrote it for his teacher and friend \plain \f1\lang1037\fs24 \u1512 \'f8' \u1504 \'f0\u1514 \'fa\u1504 \'f0\u1488 \'e0\u1500 \'ec \u1512 \'f8\u1508 \'f4\u1488 \'e0\u1500 \'ec \u1496 \'e8\u1512 \'f8\u1489 \'e1\u1493 \'e5\u1514 \'fa\plain \f2\lang1033\fs24  and finished it \plain \f1\lang1037\fs24 \u1497 \'e9\u1493 \'e5\u1501 \'ed \u1492 \'e4\u1508 \'f4\u1512 \'f8\u1513 \'f9\u1492 \'e4 \u1493 \'e5\u1497 \'e9\u1490 \'e2\u1513 \'f9 \u1513 \'f9\u1504 \'f0\u1514 \'fa \u1492 \'e4''\u1512 \'f8\u1500 \'ec \u1500 \'ec\u1508 \'f4\u1512 \'f8\u1496 \'e8 \u1493 \'e5\u1499 \'eb\u1493 \'e5\plain \f2\lang1033\fs24 '
\par \pard\fi0\li720\qj\ri0\sb0\sa0\itap0 (i. e. \plain \f2\b\lang1033\fs24 1475 -> Delitzsch hat sich verrechnet; \plain \f1\lang1037\fs24 \u1513 \'f9\u1504 \'f0\u1514 \'fa \u1492 \'e4''\u1512 \'f8\u1500 \'ec\plain \f2\b\lang1033\fs24  entspricht 1470; der Schreiber schreibt die Zahl sogar aus: \plain \f1\b\lang1037\fs24 \u1513 \'f9\u1504 \'f0\u1514 \'fa \u1495 \'e7\u1502 \'ee\u1513 \'f9\u1514 \'fa \u1488 \'e0\u1500 \'ec\u1508 \'f4\u1497 \'e9\u1501 \'ed \u1493 \'e5\u1502 \'ee\u1488 \'e0\u1514 \'fa\u1497 \'e9\u1501 \'ed \u1493 \'e5\u1513 \'f9\u1500 \'ec\u1513 \'f9\u1497 \'e9\u1501 \'ed \u1500 \'ec\u1508 \'f4\u1512 \'f8\u1496 \'e8\plain \f2\b\lang1033\fs24 )}

